// ─────────────────────────────────────────────────────────────────────────
//  12 · review this PR — SOLUTION                          ★★★ stretch
//  run: node ../run.js solutions/12-boss-review.ts
// ─────────────────────────────────────────────────────────────────────────
//
//  Walkthrough: three bugs, three classes, three one-line fixes. Each
//  one is invisible to tsc for a different reason — which is the whole
//  argument of this module in a single file.
//
//  ── BUG 1 · [create] · `||` where `??` belonged (see 03) ──────────────
//
//      reorderAt: input.reorderAt || DEFAULT_REORDER_AT
//
//  THE TELL — one input value misbehaves and only one: 0. The line above
//  it uses `??` for exactly the same job, so the file is inconsistent
//  with itself.
//  WHY TSC MISSED IT — both operators are correctly typed and produce
//  `number`. "0 is a real reorder point" is a fact about warehouses, not
//  about numbers.
//  FIX — `input.reorderAt ?? DEFAULT_REORDER_AT`.
//
//  ── BUG 2 · [apply] · a `default` that answered for a variant (see 07) ─
//
//      default: return item
//
//  THE TELL — a neutral result. `correct` did not throw and did not
//  corrupt anything; it did NOTHING, which is what a fallback does when
//  it does not recognise its input. Three cases, three union members —
//  count them.
//  WHY TSC MISSED IT — the `default` makes the switch total, so every
//  path returns an `Item` and the return type is satisfied.
//  Exhaustiveness is something you ask for; a default declines to ask.
//  FIX — the missing `case 'correct'`, plus a `never` default so the
//  next added variant is a compile error rather than a silent no-op.
//
//  ── BUG 3 · [plan] · a mutating method through an alias (see 08) ──────
//
//      const ordered = items.sort((a, b) => a.qty - b.qty);
//
//  THE TELL — the function's own answer is right and the CALLER is
//  damaged. `sort` chains like `map` and `filter` and, unlike them,
//  edits the array it was called on.
//  WHY TSC MISSED IT — `Item[]` is mutable and `sort` is legal on it.
//  TypeScript models shape, never ownership or aliasing.
//  FIX — `[...items].sort(...)`. Tightening the parameter to
//  `readonly Item[]` would have made the original line a compile error;
//  ES2023's `toSorted` is the copying method for the same job.
//
//  ── the review habit ──────────────────────────────────────────────────
//
//  Notice what all three have in common: each is a place where a runtime
//  MEANING was assumed and only a runtime TYPE was checked. When you
//  review a typed PR, tsc has already read it for shape — your job is
//  the other half: defaults (which falsy values are real?), branches
//  (which cases are missing?), and ownership (who else can see this
//  object?). Those three questions catch most of what gets past a green
//  build.

import { test, eq } from '../../_lib/check.ts';
import { use, type Expect, type Equal } from '../../_lib/type-assert.ts';

export interface Item {
  sku: string;
  name: string;
  qty: number;
  reorderAt: number;
}

export interface ItemInput {
  sku: string;
  name: string;
  qty?: number;
  reorderAt?: number;
}

export type Adjustment =
  | { kind: 'receive'; sku: string; qty: number }
  | { kind: 'ship'; sku: string; qty: number }
  | { kind: 'correct'; sku: string; qty: number };

const DEFAULT_REORDER_AT = 5;

export function createItem(input: ItemInput): Item {
  return {
    sku: input.sku,
    name: input.name,
    qty: input.qty ?? 0,
    reorderAt: input.reorderAt ?? DEFAULT_REORDER_AT,
  };
}

export function applyAdjustment(items: Item[], adj: Adjustment): Item[] {
  return items.map((item) => {
    if (item.sku !== adj.sku) return item;
    switch (adj.kind) {
      case 'receive':
        return { ...item, qty: item.qty + adj.qty };
      case 'ship':
        return { ...item, qty: Math.max(0, item.qty - adj.qty) };
      case 'correct':
        return { ...item, qty: adj.qty };
      default: {
        const unreachable: never = adj;
        throw new Error(`unhandled adjustment: ${JSON.stringify(unreachable)}`);
      }
    }
  });
}

export function applyAll(items: Item[], adjustments: Adjustment[]): Item[] {
  return adjustments.reduce(applyAdjustment, items);
}

export function restockPlan(items: Item[]): Item[] {
  const ordered = [...items].sort((a, b) => a.qty - b.qty);
  return ordered.filter((item) => item.qty <= item.reorderAt);
}

// ─────────────────────────── runtime tests ───────────────────────────────

function stock(): Item[] {
  return [
    createItem({ sku: 'bolt', name: 'Bolt', qty: 40, reorderAt: 10 }),
    createItem({ sku: 'nut', name: 'Nut', qty: 3, reorderAt: 10 }),
    createItem({ sku: 'washer', name: 'Washer', qty: 8 }),
  ];
}

test('[create] the fields left out take their defaults', () => {
  eq(createItem({ sku: 'a', name: 'A' }), {
    sku: 'a',
    name: 'A',
    qty: 0,
    reorderAt: 5,
  });
});

test('[create] a supplied reorder point is kept', () => {
  eq(createItem({ sku: 'a', name: 'A', reorderAt: 12 }).reorderAt, 12);
});

test('[create] a reorder point of zero means never reorder', () => {
  eq(createItem({ sku: 'a', name: 'A', reorderAt: 0 }).reorderAt, 0);
});

test('[apply] receive adds to the matching row', () => {
  const after = applyAll(stock(), [{ kind: 'receive', sku: 'nut', qty: 12 }]);
  eq(after[1].qty, 15);
});

test('[apply] ship subtracts and stops at zero', () => {
  const after = applyAll(stock(), [
    { kind: 'ship', sku: 'bolt', qty: 10 },
    { kind: 'ship', sku: 'nut', qty: 99 },
  ]);
  eq(after[0].qty, 30);
  eq(after[1].qty, 0);
});

test('[apply] correct sets the count outright', () => {
  const after = applyAll(stock(), [{ kind: 'correct', sku: 'nut', qty: 7 }]);
  eq(after[1].qty, 7);
});

test('[apply] rows with another sku come back untouched', () => {
  const before = stock();
  const after = applyAll(before, [{ kind: 'receive', sku: 'nut', qty: 1 }]);
  eq(after[0], before[0]);
  eq(after[2], before[2]);
});

test('[plan] lists what is at or under its reorder point', () => {
  eq(
    restockPlan(stock()).map((item) => item.sku),
    ['nut']
  );
});

test('[plan] puts the lowest count first', () => {
  const low = stock().concat(createItem({ sku: 'pin', name: 'Pin', qty: 1 }));
  eq(
    restockPlan(low).map((item) => item.sku),
    ['pin', 'nut']
  );
});

test('[plan] leaves the list it was given in its original order', () => {
  const items = stock();
  restockPlan(items);
  eq(
    items.map((item) => item.sku),
    ['bolt', 'nut', 'washer']
  );
});

// ──────────────────────────── type tests ─────────────────────────────────
//
//  These already pass — in the broken file and in the fixed one. That is
//  the whole point of the module: the type layer is satisfied either way.

type _t1 = Expect<Equal<ReturnType<typeof createItem>, Item>>;
type _t2 = Expect<Equal<Adjustment['kind'], 'receive' | 'ship' | 'correct'>>;

function _typeTests() {
  const item: Item = createItem({ sku: 'a', name: 'A' });
  use(item);

  // @ts-expect-error — an item needs a name
  createItem({ sku: 'a' });

  // @ts-expect-error — 'destroy' is not an adjustment
  applyAll([], [{ kind: 'destroy', sku: 'a', qty: 1 }]);

  // @ts-expect-error — a quantity is a number
  applyAll([], [{ kind: 'ship', sku: 'a', qty: '1' }]);
}
use(_typeTests);
